export const signName = (sign, lang) => sign.n[LANG_INDEX[lang] ?? 2] || sign.n[2];
export const signDesc = (sign, lang) => sign.d[LANG_INDEX[lang] ?? 2] || sign.d[2];
export const catName = (cat, lang) => cat.n[LANG_INDEX[lang] ?? 2];
export const catDesc = (cat, lang) => cat.d[LANG_INDEX[lang] ?? 2];
export const LANG_INDEX = { it: 0, fr: 1, en: 2, es: 3, de: 4 };

import TIPS_ES_DE from './tips-es-de.js';
ROAD_SIGNS.forEach(s => { const t = TIPS_ES_DE[s.id]; if (t && s.tip) { s.tip.es = t[0]; s.tip.de = t[1]; } });
